<script setup lang="ts">
import { onMounted, ref } from "vue";
import { http } from "@/utils/http";
type User = { id: string; username?: string; displayName?: string; email?: string; status?: string; roleCodes?: string[]; createdAt?: string; lastLoginAt?: string }; const rows = ref<User[]>([]); const loading = ref(false); const error = ref(""); const query = ref(""); const status = ref(""); const drawer = ref<any>(false); const dialog = ref(false); const form = ref({ username: "", displayName: "", email: "" });
async function load() { loading.value = true; try { const result: any = await http.get("/admin/users", { params: { query: query.value || undefined, status: status.value || undefined, page: 0, size: 100 } }); rows.value = Array.isArray(result) ? result : (result?.content || result?.items || []); } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "用户加载失败"; } finally { loading.value = false; } }
async function create() { if (!form.value.username || !form.value.displayName) { error.value = "用户名和显示名称不能为空"; return; } try { await http.post("/admin/users", { data: form.value }); dialog.value = false; form.value = { username: "", displayName: "", email: "" }; await load(); } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "用户创建失败"; } }
async function toggle(user: User) { const next = String(user.status).toUpperCase() === "DISABLED" ? "ACTIVE" : "DISABLED"; try { await http.post(`/admin/users/${user.id}/status/${next}`); await load(); if (drawer.value?.id === user.id) drawer.value = { ...user, status: next }; } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "用户状态更新失败"; } }
onMounted(load);
</script>
<template><main class="p-4 md:p-6"><div class="flex justify-between items-start gap-4 mb-6"><div><h1 class="text-2xl font-semibold">用户与角色</h1><p class="mt-1 text-[var(--el-text-color-secondary)]">管理用户状态、角色摘要和安全状态。</p></div><div class="flex gap-2"><el-button type="primary" @click="dialog = true">创建用户</el-button><el-button :loading="loading" @click="load">刷新</el-button></div></div><el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="mb-4"/><div class="flex gap-3 mb-4"><el-input v-model="query" clearable placeholder="搜索用户名" class="max-w-xs" @keyup.enter="load"/><el-select v-model="status" clearable placeholder="状态" @change="load"><el-option label="正常" value="ACTIVE"/><el-option label="已禁用" value="DISABLED"/><el-option label="已锁定" value="LOCKED"/></el-select><el-button @click="load">筛选</el-button></div><el-skeleton v-if="loading" :rows="8" animated/><el-card v-else shadow="never"><el-empty v-if="!rows.length" description="暂无用户"/><el-table v-else :data="rows" stripe @row-click="drawer = $event"><el-table-column label="用户" min-width="230"><template #default="{ row }"><div class="flex items-center gap-2"><el-avatar size="small">{{ (row.displayName || row.username || '?').slice(0,1) }}</el-avatar><div><div>{{ row.displayName }}</div><div class="text-xs text-[var(--el-text-color-secondary)]">{{ row.username }}</div></div></div></template></el-table-column><el-table-column prop="email" label="Email" min-width="220"/><el-table-column prop="status" label="状态" width="120"/><el-table-column label="Role" min-width="180"><template #default="{ row }">{{ row.roleCodes?.join('、') || '—' }}</template></el-table-column><el-table-column label="MFA" width="100">由安全策略提供</el-table-column><el-table-column prop="lastLoginAt" label="最近活动" min-width="180"/></el-table></el-card><el-dialog v-model="dialog" title="创建用户" width="480px"><el-form label-position="top"><el-form-item label="用户名" required><el-input v-model="form.username"/></el-form-item><el-form-item label="显示名称" required><el-input v-model="form.displayName"/></el-form-item><el-form-item label="Email"><el-input v-model="form.email"/></el-form-item></el-form><template #footer><el-button @click="dialog = false">取消</el-button><el-button type="primary" @click="create">创建</el-button></template></el-dialog><el-drawer v-model="drawer" title="用户详情" size="460px"><template v-if="drawer"><el-descriptions :column="1" border><el-descriptions-item label="User ID">{{ drawer.id }}</el-descriptions-item><el-descriptions-item label="显示名称">{{ drawer.displayName }}</el-descriptions-item><el-descriptions-item label="用户名">{{ drawer.username }}</el-descriptions-item><el-descriptions-item label="状态"><el-tag>{{ drawer.status }}</el-tag></el-descriptions-item><el-descriptions-item label="角色">{{ drawer.roleCodes?.join('、') || '—' }}</el-descriptions-item><el-descriptions-item label="创建时间">{{ drawer.createdAt || '—' }}</el-descriptions-item></el-descriptions><div class="flex gap-2 mt-5"><el-button @click="toggle(drawer)">{{ String(drawer.status).toUpperCase() === 'DISABLED' ? '启用' : '禁用' }}</el-button><el-button>角色与权限</el-button><el-button>会话与设备</el-button></div></template></el-drawer></main></template>
